/// <summary>
/// class <c>METTelemetryTransferOrderReceiptErrorEvent</c> is used to log error event whenever transfer order error event.
/// </summary>
internal final class METTelemetryTransferOrderReceiptErrorEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryTransferOrderReceiptErrorEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryTransferOrderReceiptErrorEvent</c> </returns>
public static METTelemetryTransferOrderReceiptErrorEvent construct()
{
    return new METTelemetryTransferOrderReceiptErrorEvent();
}

/// <summary>
/// Run confirmation journal error event 
/// </summary>
/// <param name = "_transferId"> transfer id </param>
/// <param name = "_error"> error message </param>
public static void runTelemetryEvent(InventTransferId _transferId, str _error)
{
    METTelemetryTransferOrderReceiptErrorEvent transferOrderErrorEvent = METTelemetryTransferOrderReceiptErrorEvent::construct();

    transferOrderErrorEvent.addRunTimePropertyToAppinsights(_transferId, _error);

    transferOrderErrorEvent.processEvent(METTelemetryEventNames::TOReceiptErrorEvent);
}

/// <summary>
/// Initializes the parameter setup values.
/// </summary>
/// <param name = "_parameterSetup">The parameter setup record to initialize.</param>
protected void initializeParameterSetup(ISMTelemetryParameterSetup _parameterSetup)
{
    _parameterSetup.TelemetryClass = this.telemetryName();
    _parameterSetup.IsEnabled = NoYes::Yes;
    _parameterSetup.SeverityLevel = ISMTelemetrySeverityLevel::Error;
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_transferId"> transfer id </c> </param>
public void addRunTimePropertyToAppinsights(InventTransferId _transferId, str _error)
{
    InventTransferTable inventTransferTable = InventTransferTable::find(_transferId);
    METInventTransferTableExt inventTransferTableExt = METInventTransferTableExt::findByTransferId(inventTransferTable.TransferId);

    this.addRuntimeProperty('TransferId', inventTransferTable.TransferId);
    this.addRuntimeProperty('FromWarehouseId' ,inventTransferTable.InventLocationIdFrom);
    this.addRuntimeProperty('ToWarehouseId', inventTransferTable.InventLocationIdTo);
    this.addRuntimeProperty('TransferType', enum2Str(inventTransferTableExt.TransferType));
    this.addRuntimeProperty('OrderSplitGroup', inventTransferTableExt.OrderSplitGroup);
    this.addRuntimeProperty('Message', _error);
}
